// Phone stand
stand_width = 100;          // [60:5:160]
stand_depth = 70;           // [40:5:120]
stand_height = 90;          // [40:5:160]
phone_thickness = 12;       // [6:1:25]
slot_offset_y = 12;         // [4:25]
slot_inset_z = 12;          // [4:30]
stand_color = "DimGray";

color(stand_color)
difference() {
  cube([stand_width, stand_depth, stand_height]);
  translate([
    stand_width / 2 - phone_thickness / 2,
    slot_offset_y,
    slot_inset_z,
  ])
    cube([phone_thickness, stand_depth, stand_height]);
}
